{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.inward_details_deep_analysis as with a as (SELECT upper( trim( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS SKU_group, LOWER(FINAL_TYPE) type, \"PUTAWAY_UPDATED\"::DATE as date, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS Qty, FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\"::DATE >= \'2021-09-01\' and \"PUTAWAY_UPDATED\"::DATE < \'2026-10-01\' and LOWER(FINAL_TYPE) like\'new%\' GROUP BY 1,2,3 having qty>=20 ), meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END), MIN(a.meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END), MIN(a.meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END), MIN(a.meta3) ) AS meta3, max(cogs) as cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku_2 a GROUP BY 1 ) select date,sku_group,l1_category,category,meta1,meta2,meta3,sum(qty*cogs) cogs_value,sum(qty) qty from a left join meta_map on sku_group_clean = UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) group by 1,2,3,4,5,6,7 ; create or replace table snitch_db.maplemonk.clicks_for_deep_analysis as WITH meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END), MIN(a.meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END), MIN(a.meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END), MIN(a.meta3) ) AS meta3, MAX(cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1 ) SELECT c.ga_date::DATE AS date, m.l1_category AS l1, m.category, c.sku_group, m.meta1, m.meta3, m.meta2, SUM(c.clicks) AS clicks FROM snitch_db.maplemonk.clicks_itemid c LEFT JOIN meta_map m ON m.sku_group_clean = UPPER( IFF( UPPER(REPLACE(c.SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(c.SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(c.SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(c.SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) GROUP BY 1,2,3,4,5,6,7 ORDER BY 1 DESC, l1, category, clicks DESC; create or replace table snitch_db.maplemonk.inv_deep_analysis as WITH wh_inv_raw AS ( SELECT date, TRIM(UPPER(REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), POSITION(\'-\' IN REVERSE(\"Item SkuCode\")) + 1)))) AS sku_group, UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), 1, POSITION(\'-\' IN REVERSE(\"Item SkuCode\")) - 1)))) AS raw_size, SUM(inventory) + SUM(COALESCE(\"Inventory Blocked\", 0)) + SUM(COALESCE(\"Inventory Not Synced\", 0)) + SUM(COALESCE(\"Pending Inventory Assessment\", 0)) + SUM(COALESCE(\"Putaway Pending\", 0)) + SUM(COALESCE(\"Putback Pending\", 0)) + SUM(COALESCE(\"Stock In Transfer\", 0)) AS inv_qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') GROUP BY 1, 2, 3 ), offline_sizes AS ( SELECT date, SKU_GROUP AS sku_group, \'XS\' AS raw_size, COALESCE(XS_UNITS, 0) + COALESCE(JIT_XS_UNITS, 0) AS inv_qty FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'S\', COALESCE(S_UNITS, 0) + COALESCE(JIT_S_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'M\', COALESCE(M_UNITS, 0) + COALESCE(JIT_M_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'L\', COALESCE(L_UNITS, 0) + COALESCE(JIT_L_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'XL\', COALESCE(XL_UNITS, 0) + COALESCE(JIT_XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'2XL\', COALESCE(XXL_UNITS, 0) + COALESCE(JIT_2XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'3XL\', COALESCE(XL3_UNITS, 0) + COALESCE(JIT_3XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'4XL\', COALESCE(XL4_UNITS, 0) + COALESCE(JIT_4XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'5XL\', COALESCE(XL5_UNITS, 0) + COALESCE(JIT_5XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'6XL\', COALESCE(XL6_UNITS, 0) + COALESCE(JIT_6XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'FREE SIZE\', COALESCE(inventory, 0) + COALESCE(JIT_QTY, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE COALESCE(XS_UNITS,0)+COALESCE(JIT_XS_UNITS,0) + COALESCE(S_UNITS,0)+COALESCE(JIT_S_UNITS,0) + COALESCE(M_UNITS,0)+COALESCE(JIT_M_UNITS,0) + COALESCE(L_UNITS,0)+COALESCE(JIT_L_UNITS,0) + COALESCE(XL_UNITS,0)+COALESCE(JIT_XL_UNITS,0) + COALESCE(XXL_UNITS,0)+COALESCE(JIT_2XL_UNITS,0) + COALESCE(XL3_UNITS,0)+COALESCE(JIT_3XL_UNITS,0) + COALESCE(XL4_UNITS,0)+COALESCE(JIT_4XL_UNITS,0) + COALESCE(XL5_UNITS,0)+COALESCE(JIT_5XL_UNITS,0) + COALESCE(XL6_UNITS,0)+COALESCE(JIT_6XL_UNITS,0) = 0 ), store_inv AS ( SELECT date, UPPER(TRIM(sku_group)) AS sku_group, UPPER(TRIM(raw_size)) AS raw_size, SUM(inv_qty) AS inv_qty FROM offline_sizes GROUP BY 1, 2, 3 ), myntra AS ( WITH base AS ( SELECT TRY_TO_DATE(NULLIF(TRIM(date), \'\'), \'DD-MM-YYYY\') AS date_col, gtin, soh FROM snitch_db.maplemonk.s3_myntra_inventory_test ) SELECT b.date_col AS date, UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(lm.sku), CHARINDEX(\'-\', REVERSE(lm.sku)) + 1, LEN(lm.sku))))) AS sku_group, UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(lm.sku), 1, CHARINDEX(\'-\', REVERSE(lm.sku)) - 1)))) AS raw_size, SUM(COALESCE(b.soh, 0)) AS inv_qty FROM base b LEFT JOIN snitch_db.maplemonk.logic_final_item_master lm ON lm.ean = b.gtin GROUP BY 1, 2, 3 ), flipkart AS ( WITH base AS ( SELECT TRY_TO_DATE(NULLIF(TRIM(date), \'\'), \'DD-MM-YYYY\') AS date_col, style_code, size AS raw_size, atp FROM snitch_db.maplemonk.s3_flipkart_inventory_test ) SELECT date_col AS date, UPPER(TRIM(style_code)) AS sku_group, UPPER(TRIM(raw_size)) AS raw_size, SUM(COALESCE(atp, 0)) AS inv_qty FROM base GROUP BY 1, 2, 3 ), inv_by_channel AS ( SELECT date, sku_group, raw_size, \'Warehouse\' AS channels, inv_qty FROM wh_inv_raw UNION ALL SELECT date, sku_group, raw_size, \'Offline\' AS channels, inv_qty FROM store_inv UNION ALL SELECT date, sku_group, raw_size, \'Myntra SOR\' AS channels, inv_qty FROM myntra UNION ALL SELECT date, sku_group, raw_size, \'flipkart SOR\' AS channels, inv_qty FROM flipkart ), inv_norm AS ( SELECT date, sku_group, CASE WHEN raw_size IS NULL OR TRIM(raw_size) = \'\' THEN \'L\' WHEN raw_size = \'01M\' THEN \'M\' WHEN raw_size = \'01XL\' THEN \'XL\' WHEN raw_size = \'06XL\' THEN \'6XL\' WHEN raw_size IN (\'XS\', \'S\', \'M\', \'L\', \'XL\') THEN raw_size WHEN raw_size IN (\'XXL\', \'2XL\', \'XXU\') THEN \'2XL\' WHEN raw_size IN (\'XXXL\', \'3XL\') THEN \'3XL\' WHEN raw_size IN (\'4XL\', \'5XL\', \'6XL\', \'7XL\', \'8XL\') THEN raw_size WHEN raw_size = \'28\' THEN \'XS\' WHEN raw_size = \'30\' THEN \'S\' WHEN raw_size = \'32\' THEN \'M\' WHEN raw_size = \'34\' THEN \'L\' WHEN raw_size = \'36\' THEN \'XL\' WHEN raw_size = \'38\' THEN \'2XL\' WHEN raw_size = \'40\' THEN \'3XL\' WHEN raw_size = \'42\' THEN \'4XL\' WHEN raw_size = \'44\' THEN \'5XL\' WHEN raw_size = \'46\' THEN \'6XL\' WHEN raw_size = \'48\' THEN \'7XL\' WHEN raw_size = \'50\' THEN \'8XL\' WHEN raw_size = \'39\' THEN \'2XL\' WHEN raw_size = \'41\' THEN \'4XL\' WHEN raw_size = \'43\' THEN \'5XL\' WHEN raw_size = \'45\' THEN \'6XL\' WHEN raw_size = \'1\' THEN \'XS\' WHEN raw_size = \'2\' THEN \'S\' WHEN raw_size = \'3\' THEN \'M\' WHEN raw_size = \'4\' THEN \'L\' WHEN raw_size = \'5\' THEN \'XL\' WHEN raw_size = \'6\' THEN \'2XL\' ELSE raw_size END AS size, channels, inv_qty FROM inv_by_channel ) SELECT date, sku_group, size, channels, SUM(inv_qty) AS inv FROM inv_norm GROUP BY 1, 2, 3, 4 HAVING SUM(inv_qty) > 0 ORDER BY date, channels, CASE size WHEN \'XS\' THEN 1 WHEN \'S\' THEN 2 WHEN \'M\' THEN 3 WHEN \'L\' THEN 4 WHEN \'XL\' THEN 5 WHEN \'2XL\' THEN 6 WHEN \'3XL\' THEN 7 WHEN \'4XL\' THEN 8 WHEN \'5XL\' THEN 9 WHEN \'6XL\' THEN 10 ELSE 11 END;",
                    "transaction": true
                }
            ) }}
